d #ddd;\n  }\n\n  .desglose-item td {\n    padding: 2px 3px;\n  }\n\n  .desglose-label {\n    font-weight: bold;\n  }\n\n  .desglose-value {\n    text-align: right;\n    font-family: '\''Courier New'\'', monospace;\n    font-weight: bold;\n  }\n\n  .desglose-total {\n    border-top: 2px solid #000;\n    border-bottom: 2px solid #000;\n    font-weight: bold;\n  }\n\n  .mensaje-table {\n    border: 2px solid #000;\n    margin-bottom: 5px;\n    width: 100%;\n  }\n\n  .mensaje-label {\n    font-weight: bold;\n    font-size: 9px;\n    padding: 3px 5px;\n  }\n\n  .mensaje-contenido {\n    height: 30px;\n    padding: 5px;\n    background: #f9f9f9;\n  }\n\n  .aviso-importante {\n    text-align: center;\n    font-weight: bold;\n    font-size: 9px;\n    border-top: 1px solid #000;\n    border-bottom: 1px solid #000;\n    padding: 5px;\n    margin: 5px 0;\n  }\n\n  .talon-table {\n    border: 2px solid #000;\n    width: 100%;\n  }\n\n  .talon-label {\n    font-weight: bold;\n    font-size: 9px;\n    padding: 3px 5px;\n    background: #f0f7ff;\n  }\n\n  .talon-contenido {\n    padding: 5px;\n    background: #f0f7ff;\n    font-size: 9px;\n    line-height: 1.4;\n  }\n</style>\n\n<!-- HEADER -->\n<table class=\"header-table\">\n  <tr>\n    <td class=\"header-logo\">LOGO</td>\n    <td class=\"header-nombre\">\n      <div class=\"header-nombre-title\">PREVISORA DEL NORTE</div>\n      <div class=\"header-nombre-subtitle\">Servicios Sociales</div>\n      <div class=\"header-nombre-dir\">San Miguel 323, Bovril, Entre Ríos</div>\n    </td>\n    <td class=\"header-item\">\n      <div class=\"header-item-label\">Teléfono</div>\n      <div class=\"header-item-value\">03438-421645</div>\n    </td>\n    <td class=\"header-item\">\n      <div class=\"header-item-label\">Recibo "C"</div>\n      <div class=\"header-item-value\">{{numero_recibo}}</div>\n    </td>\n    <td class=\"header-item\">\n      <div class=\"header-item-label\">Asociado</div>\n      <div class=\"header-item-value\">{{numero_afiliado}}</div>\n    </td>\n    <td class=\"header-item\">\n      <div class=\"header-item-label\">Plan</div>\n      <div class=\"header-item-value\">{{tipo_plan_nombre}}</div>\n    </td>\n    <td class=\"header-item\">\n      <div class=\"header-item-label\">Composición</div>\n      <div class=\"header-item-value\">{{tipo_de_grupo_nombre}}</div>\n    </td>\n    <td>\n      <div class=\"header-item-label\">Beneficios y Coberturas</div>\n    </td>\n  </tr>\n</table>\n\n<!-- CONTENIDO PRINCIPAL -->\n<table class=\"contenido-table\">\n  <tr>\n    <td class=\"seccion-izq\">\n      <table class=\"datos-table\">\n        <tr>\n          <td class=\"datos-label\">Titular Adherente:</td>\n          <td><b>{{titular_apellido}}, {{titular_nombre}}</b></td>\n        </tr>\n        <tr>\n          <td class=\"datos-label\">Fecha Nacimiento:</td>\n          <td>{{fecha_nacimiento}}</td>\n        </tr>\n        <tr>\n          <td class=\"datos-label\">Fecha Cobertura:</td>\n          <td>{{fecha_cobertura}}</td>\n        </tr>\n        <tr>\n          <td class=\"datos-label\">Documento:</td>\n          <td>{{numero_documento}}</td>\n        </tr>\n      </table>\n    </td>\n    <td class=\"seccion-centro\"></td>\n    <td class=\"seccion-der\">\n      <table class=\"datos-table\" style=\"margin-bottom: 5px;\">\n        <tr>\n          <td class=\"datos-label\">Domicilio:</td>\n          <td>{{domicilio}}</td>\n        </tr>\n        <tr>\n          <td class=\"datos-label\">Localidad:</td>\n          <td>{{localidad_nombre}}</td>\n        </tr>\n        <tr>\n          <td class=\"datos-label\">Mes y Año:</td>\n          <td>{{periodo}}</td>\n        </tr>\n      </table>\n      <table class=\"desglose-table\">\n        <tr class=\"desglose-item\">\n          <td class=\"desglose-label\">Cuota Social:</td>\n          <td class=\"desglose-value\">{{cuota_social}}</td>\n        </tr>\n        <tr class=\"desglose-item\">\n          <td class=\"desglose-label\">Arancel por Serv:</td>\n          <td class=\"desglose-value\">{{arancel_por_servicio}}</td>\n        </tr>\n        <tr class=\"desglose-item desglose-total\">\n          <td class=\"desglose-label\">Total Cuota:</td>\n          <td class=\"desglose-value\">{{valor_cuota}}</td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n\n<!-- SECCIÓN MENSAJE -->\n<table class=\"mensaje-table\">\n  <tr>\n    <td class=\"mensaje-label\">Mensaje:</td>\n  </tr>\n  <tr>\n    <td class=\"mensaje-contenido\"></td>\n  </tr>\n</table>\n\n<!-- AVISO IMPORTANTE -->\n<div class=\"aviso-importante\">\nLA FALTA DE PAGO DE DOS CUOTAS CONSECUTIVAS PRODUCE LA MORA AUTOMÁTICA\n</div>\n\n<!-- TALÓN DEL COBRADOR -->\n<table class=\"talon-table\">\n  <tr>\n    <td class=\"talon-label\">Talón para el cobrador:</td>\n  </tr>\n  <tr>\n    <td class=\"talon-contenido\">\nAfil. N:{{numero_afiliado}} {{titular_apellido}} {{titular_nombre}}\nRecibo N {{numero_recibo}} Fecha: {{periodo}} {{valor_cuota}}\n    </td>\n  </tr>\n</table>',
